'use strict';

// MODULES //

var tape = require( 'tape' );
var abs = require( '@stdlib/math/base/special/abs' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var EPS = require( '@stdlib/constants/float64/eps' );
var incrnanmpe = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmpe, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanmpe(), 'function', 'returns expected value' );
	t.end();
});

tape( 'the initial accumulated value is `null`', function test( t ) {
	var acc = incrnanmpe();
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function incrementally computes the mean percentage error, ignoring NaN values', function test( t ) {
	var expected;
	var actual;
	var delta;
	var data;
	var acc;
	var sum;
	var tol;
	var cnt;
	var N;
	var x;
	var y;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, NaN ],  // NaN in actual - should be skipped
		[ 3.0, 5.0 ],
		[ NaN, 4.0 ],  // NaN in forecast - should be skipped
		[ 1.0, 10.0 ],
		[ NaN, NaN ]  // NaN in both - should be skipped
	];
	N = data.length;

	acc = incrnanmpe();

	sum = 0;
	cnt = 0;
	for ( i = 0; i < N; i++ ) {
		x = data[ i ][ 0 ];
		y = data[ i ][ 1 ];
		actual = acc( x, y );
		if ( isnan( x ) === false && isnan( y ) === false ) {
			sum += ( y-x ) / y;
			cnt += 1;
			expected = 100.0 * ( sum/cnt );
		}
		if ( actual === expected ) {
			t.strictEqual( actual, expected, 'returns expected value' );
		} else {
			delta = abs( expected - actual );
			tol = 10.0 * EPS * abs( expected );
			t.strictEqual( delta <= tol, true, 'within tolerance. Actual: '+actual+'. Expected: '+expected+'. Delta: '+delta+'. Tol: '+tol+'.' );
		}
	}
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current mean percentage error', function test( t ) {
	var expected;
	var actual;
	var delta;
	var data;
	var acc;
	var tol;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ NaN, 5.0 ],  // Should be skipped
		[ 3.0, 5.0 ],
		[ 1.0, 10.0 ]
	];
	acc = incrnanmpe();
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ][ 0 ], data[ i ][ 1 ] );
	}
	actual = acc();

	// Only counting non-NaN: [2.0, 3.0], [3.0, 5.0], [1.0, 10.0]
	expected = 100.0 / 3.0 * ((1.0/3.0) + (2.0/5.0) + (9.0/10.0));
	delta = abs( expected - actual );
	tol = 1.0 * EPS * abs( expected );
	t.strictEqual( delta <= tol, true, 'within tolerance. Actual: '+actual+'. Expected: '+expected+'. Delta: '+delta + '. Tol: '+tol+'.' );
	t.end();
});
